function build(rows, brand) {
  const out = {};
  for (const [title, hook, pillar, problem, slides, caption, hashtags] of rows) {
    out[title.toLowerCase()] = {
      title, hook, pillar, problem,
      carousel: {
        slides: slides.map(([headline, body], i) => ({ headline, body, design_note: NOTE[brand][i] })),
        caption, hashtags, cta: slides[4][1],
      },
    };
  }
  return out;
}

export const LIBRARY = { elevara: build(E, 'elevara'), sister: build(S, 'sister'), personal: build(P, 'personal') };
export const libraryFor = (brand, title) => LIBRARY[brand]?.[(title || '').toLowerCase()] || LIBRARY.elevara[(title || '').toLowerCase()] || null;
